CREATE TABLE finance_reconciliation (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,account_id UUID NOT NULL,owner_id UUID NOT NULL,statement_date DATE NOT NULL,statement_balance NUMERIC(19,4) NOT NULL,calculated_balance NUMERIC(19,4) NOT NULL,difference NUMERIC(19,4) NOT NULL,status VARCHAR(24) NOT NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(status IN ('OPEN','MATCHED','DIFFERENCE','CLOSED')),FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),FOREIGN KEY(account_id) REFERENCES finance_account(id)); CREATE INDEX idx_finance_reconciliation ON finance_reconciliation(ledger_id,statement_date DESC);
